const D = { scale:1, energy:.7, hue:20, speed:1, density:.5, x:.5, y:.72, style:'sticker', width:.5, gloss:.6, bars:.6, seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- helpers ----
const md = (a,n)=>((a%n)+n)%n;
const frc = v=>v-Math.floor(v);
const clp = (v,a,b)=>Math.max(a,Math.min(b,v));
const ez = t=>{t=clp(t,0,1);return t*t*(3-2*t);};
const fr = i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
if (S.lastBeat==null || K.beat<S.lastBeat) S.lastBeat=K.beat;
S.lastBeat=K.beat;

const u = Math.min(width,height);
const sc = u*P.scale/320;
const bt = K.beat*P.speed;
const H = md(P.hue,360);
const style = P.style;
const sticker=style==='sticker', chrome=style==='chrome', xray=style==='xray', riso=style==='riso', night=style==='night';
const en = P.energy*(.5+.6*K.intensity);

// bass/cone drive: clk baseline + audio on top (baseline must carry when silent)
const thumpB = K.pulse*.55 + K.swell*.35;             // baseline pump
const thump = thumpB + A.bass*.8 + A.lowmid*.4;
const kick = K.pulse*.6 + A.bass*.85;

// geometry
const BW = 118 + P.width*40;    // body half-width
const BH = 78;                  // body half-height
const coneR = 46;               // woofer radius
const coneX = BW*.52;           // woofer offset

// ---- seed-keyed sticker layout ----
if (S.seedUsed!==P.seed) {
  S.seedUsed=P.seed;
  S.stk=[];
  const kinds=['star','bolt','circ','bubble','tri','ring'];
  for (let i=0;i<44;i++) S.stk.push({
    x:(fr(i*2+1)-.5)*(BW*1.7), y:(fr(i*2+2)-.5)*(BH*1.5),
    r:9+fr(i*3+4)*15, rot:(fr(i*3+5)-.5)*1.2, k:kinds[Math.floor(fr(i*3+6)*6)],
    h:Math.floor(fr(i*4+7)*360), ph:fr(i*5+9)*6.28
  });
  S.eqSeed=[]; for(let i=0;i<16;i++) S.eqSeed.push(fr(i*11+2));
}

// whole-box rock on the beat
const rock = Math.sin(bt*Math.PI)*.03*en + kick*.015;
const boxLift = -kick*7*en - K.swell*3*en;
const swayX = Math.sin(K.t*.5)*6*en;

// ---- sticker shapes ----
function drawSticker(s){
  push(); translate(s.x, s.y); rotate(s.rot + Math.sin(K.t*.3+s.ph)*.05);
  const wob = 1 + Math.sin(K.t*1.4+s.ph)*.04;
  scale(wob);
  // die-cut white border + drop shadow
  noStroke(); fill(0,0,0,30);
  const R=s.r;
  const fillH = riso?(s.k==='star'?358:200):(night?s.h:s.h);
  const sat = riso?85:(night?70:82), bri=night?85:92;
  // shadow offset
  push(); translate(2.5,3); fill(0,0,0,28); shp(s.k,R*1.14); pop();
  fill(0,0,100); shp(s.k,R*1.14);      // white border
  fill(fillH,sat,bri); shp(s.k,R);     // color
  // gloss highlight
  if (P.gloss>.05){ fill(0,0,100, 40*P.gloss); ellipse(-R*.22,-R*.28,R*.5,R*.32); }
  pop();
}
function shp(k,R){
  if (k==='circ'||k==='ring'){ ellipse(0,0,R*2,R*2); if(k==='ring'){fill(0,0,0,0);} }
  else if (k==='star'){ star(0,0,R*.5,R,5); }
  else if (k==='bolt'){ beginShape(); vertex(-.2*R,-R);vertex(.4*R,-.1*R);vertex(.05*R,-.1*R);vertex(.3*R,R);vertex(-.4*R,.1*R);vertex(0,.1*R); endShape(CLOSE); }
  else if (k==='tri'){ triangle(0,-R,R*.9,R*.7,-R*.9,R*.7); }
  else { rect(-R,-R*.7,R*2,R*1.4,R*.4); }  // bubble
}
function star(cx,cy,r1,r2,n){ beginShape(); for(let i=0;i<n*2;i++){const a=i/(n*2)*6.2832-1.57;const r=i%2?r1:r2;vertex(cx+Math.cos(a)*r,cy+Math.sin(a)*r);} endShape(CLOSE); }

// ---- woofer cone ----
function woofer(cx){
  push(); translate(cx,0);
  const pump = 1 + thump*.16;
  // surround / basket
  if (xray){
    stroke(180,60,100,80); strokeWeight(1.4); noFill();
    for(let r=coneR;r>4;r-=6) ellipse(0,0,r*2,r*2);
    line(-coneR,0,coneR,0); line(0,-coneR,0,coneR);
    // magnet behind (schematic)
    stroke(180,50,100,50); rect(-coneR*.5,-coneR*.5,coneR,coneR);
    pop(); return;
  }
  noStroke();
  fill(0,0, night?8:14); ellipse(0,0,coneR*2.15,coneR*2.15);       // frame
  fill(0,0, night?4:8); ellipse(0,0,coneR*2,coneR*2);
  // concentric cone rings pumping
  const rings = chrome?6:5;
  for (let i=rings;i>=1;i--){
    const rr = coneR*(i/rings)*pump;
    const lit = night? (i%2? 12: 20) : (chrome? (i%2?70:22) : (i%2? 30:16));
    fill(riso?200:H*0+0, riso?70:0, lit, 100);
    if (riso){ fill(i%2?200:358, 65, lit+8); }
    else if (!chrome && !night){ fill(H, 30, lit*1.1); }
    ellipse(0,0,rr*2,rr*2);
  }
  // dust cap (glows on kick)
  fill(night? md(H,360):H, night?90:60, clp((night?40:55)+thump*45,0,100));
  ellipse(0,0, coneR*.5*pump, coneR*.5*pump);
  // specular
  fill(0,0,100, 30*P.gloss + thump*20);
  ellipse(-coneR*.28,-coneR*.3, coneR*.55, coneR*.4);
  pop();
}

// ---- render ----
push();
translate(P.x*width + swayX*sc, P.y*height);
scale(sc);
rotate(rock);
translate(0, boxLift);

// glow behind (ADD, bass)
if (!xray){
  blendMode(ADD); noStroke();
  fill(md(H+ (night?200:0),360),70,100, clp(8+kick*22+K.swell*8,0,38));
  ellipse(0,0,(BW+70)*2, (BH+50)*2*.7);
  blendMode(BLEND);
}

// ground shadow
noStroke(); fill(0,0,0,34); ellipse(0, BH+26, (BW+30)*2, 26);

// ===== BODY =====
// carry handle (sways)
push();
const hsw = Math.sin(K.t*.8)*.04*en + rock*.5;
translate(0,-BH); rotate(hsw*0);
if (xray){ stroke(180,60,100,70); strokeWeight(2); noFill(); }
else { stroke(0,0, night?25:20); strokeWeight(9); noFill(); }
arc(0, -6, BW*1.1, BH*1.1, Math.PI+.3+hsw, 6.2832-.3+hsw);
pop();

// body slab
if (xray){
  stroke(190,60,100,85); strokeWeight(1.6); noFill();
  rect(-BW,-BH,BW*2,BH*2, 12);
  // internal boards
  stroke(190,45,100,45); strokeWeight(1);
  for(let i=0;i<4;i++) line(-BW+20,-BH+20+i*30, BW-20,-BH+20+i*30);
} else {
  // outer shell
  noStroke();
  const shellB = night?16: chrome?58: riso?90:78, shellS = night?30: chrome?6: riso?15:12;
  fill(chrome?210:H, shellS, shellB); rect(-BW-6,-BH-6,(BW+6)*2,(BH+6)*2, 16);   // bezel
  fill(chrome?210:H, shellS*.6, shellB*.82); rect(-BW,-BH,BW*2,BH*2, 12);         // face
  // brushed metal streaks / gloss top band
  if (chrome){ for(let i=0;i<10;i++){ fill(210,6, i%2?80:40, 30); rect(-BW,-BH+i*(BH*2/10),BW*2, BH*2/10); } }
  fill(0,0,100, 22*P.gloss); rect(-BW,-BH,BW*2, BH*.5, 10);                        // top gloss
}

// tape deck (center) with two spinning reels
push(); translate(0, -BH*.28);
const dw = BW*.72, dh = BH*.5;
if (xray){ stroke(190,55,100,70); strokeWeight(1.3); noFill(); rect(-dw,-dh,dw*2,dh*2,4); }
else { noStroke(); fill(0,0, night?5:10); rect(-dw,-dh,dw*2,dh*2,4);
  fill(200,40, night?18:30, 55); rect(-dw+3,-dh+3,dw*2-6,dh*2-6,3); }   // window tint
// reels spin continuously from beat clock
const spin = K.beat*1.4*P.speed;
for (let g=-1;g<=1;g+=2){
  push(); translate(g*dw*.5, 0); rotate(spin*g);
  if (xray){ stroke(190,60,100,80); strokeWeight(1.2); noFill(); ellipse(0,0,dh*1.1,dh*1.1);
    for(let i=0;i<3;i++){const a=i/3*3.1416;line(-Math.cos(a)*dh*.5,-Math.sin(a)*dh*.5,Math.cos(a)*dh*.5,Math.sin(a)*dh*.5);} }
  else { noStroke(); fill(0,0,88); ellipse(0,0,dh*1.05,dh*1.05); fill(0,0, night?12:14); ellipse(0,0,dh*.5,dh*.5);
    for(let i=0;i<6;i++){const a=i/6*6.2832; fill(0,0,20); ellipse(Math.cos(a)*dh*.32,Math.sin(a)*dh*.32,dh*.16,dh*.16);} }
  pop();
}
pop();

// EQ / VU bars (A.fft with clk baseline when silent)
push(); translate(0, BH*.44);
const nb = Math.floor(6 + P.bars*10);
const bw = (BW*1.5)/nb;
for (let i=0;i<nb;i++){
  const fftv = (A.fft && A.fft.length) ? A.fft[Math.floor(i/nb*A.fft.length)]||0 : 0;
  const base = .28 + .5*Math.abs(Math.sin(bt*Math.PI + i*.6 + S.eqSeed[i]*6.28)) * (.5+.5*K.intensity);
  const lvl = clp(base*.7 + fftv*1.1 + kick*.2, .05, 1);
  const bx = -BW*.75 + i*bw + bw*.5;
  const bhh = lvl*BH*.5;
  if (xray){ stroke(150,60,100,70); strokeWeight(1); noFill(); rect(bx-bw*.35,0,bw*.7,-bhh); }
  else {
    noStroke();
    const seg = Math.ceil(bhh/5);
    for (let sgi=0; sgi<seg; sgi++){
      const yy=-sgi*5; const frac=sgi/Math.max(1,(BH*.5/5));
      const bh2 = frac<.6? 130 : frac<.85? 55 : 0;   // green->yellow->red
      fill(night?bh2:bh2, night?85:80, night?85:75, night?100:95);
      rect(bx-bw*.35, yy, bw*.7, -4, 1);
    }
  }
}
pop();

// woofers (front)
woofer(-coneX);
woofer(coneX);
// tweeter + knobs between
if (!xray){
  noStroke(); fill(0,0,night?10:18); ellipse(0,BH*.02,BW*.16,BW*.16);
  fill(night? md(H,360):45, 60, clp(45+A.treble*50+K.swell*20,0,100)); ellipse(0,BH*.02,BW*.08,BW*.08);
  // knobs
  for(let g=-1;g<=1;g+=2){ push(); translate(g*BW*.24,-BH*.02); fill(0,0,70); ellipse(0,0,BW*.1,BW*.1);
    stroke(0,0,20); strokeWeight(1.5); const ka=K.t*.4+g; line(0,0,Math.cos(ka)*BW*.04,Math.sin(ka)*BW*.04); noStroke(); pop(); }
}

// sticker-bomb overlay (only sticker style) — dense die-cut collage
if (sticker){
  const n = Math.floor(10 + P.density*34);
  for (let i=0;i<n;i++) drawSticker(S.stk[i]);
}
// riso misregistration: draw shell outline offset in 2nd ink
if (riso){
  noFill(); stroke(200,70,90,55); strokeWeight(2); rect(-BW+3,-BH-2,BW*2,BH*2,12);
  stroke(358,80,90,45); rect(-BW-3,-BH+2,BW*2,BH*2,12);
}

pop();
blendMode(BLEND);
